class Car {
  constructor(brand, model, year) {
    this.brand = brand;
    this.model = model;
    this.year = year;
    this.mileage = 0;
    this.isRunning = false;
  }

  start() {
    this.isRunning = true;
    return `${this.brand} ${this.model} is now running`;
  }

  stop() {
    this.isRunning = false;
    return `${this.brand} ${this.model} stopped`;
  }

  drive(distance) {
    if (this.isRunning) {
      this.mileage += distance;
      return `Drove ${distance}km. Total: ${this.mileage}km`;
    }
    return 'Start the car first!';
  }
}

const myCar = new Car('Toyota', 'Corolla', 2023);
console.log(myCar.start());
console.log(myCar.drive(50));
console.log(myCar.drive(30));

function assert(condition, message) {
  if (!condition) {
    throw new Error(`Assertion failed: ${message}`);
  }
  console.log(`✓ ${message}`);
}

function add(a, b) {
  return a + b;
}

function multiply(a, b) {
  return a * b;
}

function isEven(num) {
  return num % 2 === 0;
}

assert(add(2, 3) === 5, 'add(2, 3) should equal 5');
assert(add(0, 0) === 0, 'add(0, 0) should equal 0');
assert(add(-1, 1) === 0, 'add(-1, 1) should equal 0');

assert(multiply(3, 4) === 12, 'multiply(3, 4) should equal 12');
assert(multiply(0, 5) === 0, 'multiply(0, 5) should equal 0');

assert(isEven(4) === true, 'isEven(4) should be true');
assert(isEven(7) === false, 'isEven(7) should be false');

function validateEmail(email) {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
}

function validatePassword(password) {
  return password.length >= 8;
}

function validateAge(age) {
  return age >= 0 && age <= 150;
}

const tests = [
  { fn: validateEmail, input: 'nacho@example.com', expected: true },
  { fn: validateEmail, input: 'invalid', expected: false },
  { fn: validateEmail, input: 'test@test', expected: false },
  { fn: validatePassword, input: 'password123', expected: true },
  { fn: validatePassword, input: 'short', expected: false },
  { fn: validateAge, input: 25, expected: true },
  { fn: validateAge, input: -5, expected: false },
  { fn: validateAge, input: 200, expected: false },
];

tests.forEach(({ fn, input, expected }) => {
  const result = fn(input);
  console.log(result === expected ? '✓ PASS' : '✗ FAIL', fn.name, input);
});

const Calculator = (function() {
  let result = 0;

  function add(num) {
    result += num;
    return this;
  }

  function subtract(num) {
    result -= num;
    return this;
  }

  function multiply(num) {
    result *= num;
    return this;
  }

  function getResult() {
    return result;
  }

  function reset() {
    result = 0;
    return this;
  }

  return { add, subtract, multiply, getResult, reset };
})();

Calculator.add(10).multiply(2).subtract(5);
console.log(Calculator.getResult());

Calculator.reset().add(100).subtract(50);
console.log(Calculator.getResult());
